 /** "N songs" with the language's plural form. */
 public static String songs(int n){
  String lang=Locale.getDefault().getLanguage();String form;
  if(lang.equals("uk") || lang.equals("ru")){int m10=n%10,m100=n%100;form=m10==1 && m100!=11?"songs_one":m10>=2 && m10<=4 && (m100<12 || m100>14)?"songs_few":"songs_many";}
  else if(lang.equals("ar")){int m100=n%100;form=n==1?"songs_one":m100>=3 && m100<=10?"songs_few":"songs_many";}
  else form=n==1?"songs_one":"songs_few";
  return String.format(Locale.getDefault(),get(form),n);
 }
